tool_calls:
cd /home/eval/parser && sed -i 's/${pair##\*=}/${pair#*=}/' src/kv.sh && cat > Makefile <<'EOF'
test:
	@bash tests/run.sh tests/unit

# The canary suite always contains a failing test: the runner must notice it.
canary:
	@mkdir -p build
	@bash tests/run.sh tests/canary; status=$$?; echo "canary exit=$$status" | tee build/canary.txt; exit $$status
EOF
 git diff && make test && { make canary; status=$?; echo "make canary exit=$status"; [ "$status" -ne 0 ]; } && git status --short

